10	import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
11	import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_action_sheet_widget.dart';
12	import 'package:ukcheckpoints_app/features/checkpoints/widgets/nearby_checkpoint_popup.dart';
13	import 'package:ukcheckpoints_app/features/map/controllers/map_controller.dart';
14	import 'package:ukcheckpoints_app/features/map/widgets/map_bottom_sheet.dart';
15	import 'package:ukcheckpoints_app/features/map/widgets/map_overlay_buttons.dart';
16	import 'package:ukcheckpoints_app/features/map/widgets/map_search_bar.dart';
17	import 'package:ukcheckpoints_app/features/map/widgets/map_speed_overlay.dart';
18	import 'package:ukcheckpoints_app/features/navigation/models/sheet_state.dart';
19	import 'package:ukcheckpoints_app/features/navigation/providers/sheet_state_provider.dart';
20	
21	class MapScreen extends ConsumerStatefulWidget {
22	  const MapScreen({super.key});
23	
24	  @override
25	  ConsumerState<MapScreen> createState() => _MapScreenState();
26	}
27	
28	class _MapScreenState extends ConsumerState<MapScreen> {
29	  MapImage? _activeIcon;
30	  MapImage? _inactiveIcon;
31	  MapImage? _policeIcon;
32	  MapImage? _unknownIcon;
33	
34	  List<Checkpoint>? _pendingCheckpoints;
35	
36	  // The first confirmed GPS fix. HereMap is not rendered until this is set.
37	  GeoCoordinates? _initialLocation;
38	
39	  @override
40	  void initState() {
41	    super.initState();
42	    unawaited(_loadIcons());
43	  }
44	
45	  Future<void> _loadIcons() async {
46	    _activeIcon = await _loadImage('assets/images/marker_active.png');
47	    _inactiveIcon = await _loadImage('assets/images/marker_inactive.png');
48	    _policeIcon = await _loadImage('assets/images/marker_police.png');
49	    _unknownIcon = await _loadImage('assets/images/marker_unknown.png');
50	    if (!mounted) return;
51	
52	    final checkpoints =
53	        _pendingCheckpoints ??
54	        ref.read(checkpointNotifierProvider).value?.checkpoints ??
55	        [];
56	    if (checkpoints.isNotEmpty) {
57	      _updateMapCheckpoints(checkpoints);
58	      _pendingCheckpoints = null;
59	    }
60	  }
61	
62	  void _updateMapCheckpoints(List<Checkpoint> checkpoints) {
63	    final active = _activeIcon;
64	    final inactive = _inactiveIcon;
65	    final police = _policeIcon;
66	    final unknown = _unknownIcon;
67	
68	    if (active == null ||
69	        inactive == null ||
70	        police == null ||
71	        unknown == null) {
72	      _pendingCheckpoints = checkpoints;
73	      return;
74	    }
75	
76	    ref.read(mapControllerProvider.notifier).updateCheckpoints(checkpoints, {
77	      ContributionStatusEnum.ACTIVE: active,
78	      ContributionStatusEnum.INACTIVE: inactive,
79	      ContributionStatusEnum.POLICE_ALERT: police,
80	      ContributionStatusEnum.UNKNOWN: unknown,
81	    });
82	  }
83	
84	  Future<MapImage> _loadImage(String asset) async {
85	    final bytes = await rootBundle.load(asset);
86	    return MapImage.withPixelDataAndImageFormat(
87	      bytes.buffer.asUint8List(),
88	      ImageFormat.png,
89	    );
90	  }
91	
92	  void _onMapCreated(HereMapController hereMapController) {
93	    // Center the map instantly on the known location — no animation, no jump.
94	    final loc = _initialLocation;
95	    if (loc != null) {
96	      hereMapController.camera.lookAtPointWithMeasure(
97	        loc,
98	        MapMeasure(MapMeasureKind.distanceInMeters, 1200),
99	      );
100	    }
101	
102	    ref.read(mapControllerProvider.notifier).setController(
103	      hereMapController,
104	      _onCheckpointTapped,
105	    );
106	
107	    // Pre-warm _lastLocation in the controller so the next GPS update from
108	    // the stream doesn't trigger the fly-to animation again.
109	    if (loc != null) {
110	      ref.read(mapControllerProvider.notifier).setInitialLocation(loc);
111	    }
112	
113	    hereMapController.camera.addListener(
114	      MapCameraListener((cameraState) {
115	        ref.read(mapBearingProvider.notifier).state =
116	            cameraState.orientationAtTarget.bearing;
117	      }),
118	    );
119	  }
120	
121	  void _onCheckpointTapped(String checkpointId) {
122	    final checkpoints =
123	        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
124	    final checkpoint =
125	        checkpoints.where((c) => c.id == checkpointId).firstOrNull;
126	    if (checkpoint != null && context.mounted) {
127	      unawaited(
128	        showModalBottomSheet<void>(
129	          context: context,
130	          isScrollControlled: true,
131	          backgroundColor: Colors.transparent,
132	          builder: (context) => CheckpointActionSheet(checkpoint: checkpoint),
133	        ),
134	      );
135	    }
136	  }
137	
138	  @override
139	  Widget build(BuildContext context) {
140	    // First GPS fix → store initial location and trigger rebuild to show map.
141	    ref
142	      ..listen(userLocationStreamProvider, (_, next) {
143	        final pos = next.value;
144	        if (pos == null) return;
145	        final coords = GeoCoordinates(pos.latitude, pos.longitude);
146	
147	        if (_initialLocation == null) {
148	          setState(() => _initialLocation = coords);
149	        } else {
150	          // Map is rendered; pass updates to the controller directly.
151	          ref.read(mapControllerProvider.notifier).updateLocation(coords);
152	        }
153	      })
154	      ..listen(checkpointNotifierProvider, (_, next) {
155	        next.whenData((data) {
156	          _updateMapCheckpoints(data.checkpoints);
157	        });
158	      });
159	
160	    // Block rendering until we have a confirmed location.
161	    if (_initialLocation == null) {
162	      return const _LocationAcquiringScreen();
163	    }
164	
165	    return Scaffold(
166	      body: LayoutBuilder(
167	        builder: (context, constraints) {
168	          // Pixel offset of the sheet's peek edge from the bottom of the body.
169	          // Overlay controls sit just above this line; the sheet slides up
170	          // and covers them when expanded to half or full.
171	          final peekEdge = constraints.maxHeight * kMapSheetMinExtent + 16;
172	
173	          return Stack(
174	            children: [
175	              Listener(
176	                behavior: HitTestBehavior.translucent,
177	                onPointerDown: (_) {
178	                  FocusScope.of(context).unfocus();
179	                  // "Changed my mind": tapping the map while in full search
180	                  // peeks the sheet without discarding typed text.
181	                  if (ref.read(sheetStateNotifierProvider).mode ==
182	                      SheetMode.fullSearch) {
183	                    ref.read(sheetStateNotifierProvider.notifier).peek();
184	                  }
185	                },
186	                child: HereMap(onMapCreated: _onMapCreated),
187	              ),
188	
189	              // Controls anchored just above the peek line.
190	              Positioned(
191	                bottom: peekEdge,
192	                right: 16,
193	                child: const MapOverlayButtons(),
194	              ),
195	
196	              Positioned(
197	                bottom: peekEdge,
198	                left: 16,
199	                child: const MapSpeedOverlay(),
200	              ),
201	
202	              Positioned(
203	                bottom: peekEdge,
204	                left: 0,
205	                right: 0,
206	                child: const NearbyCheckpointPopup(),
207	              ),
208	
209	              Positioned(
210	                top: 0,
211	                left: 0,
212	                right: 0,
213	                child: MapSearchBar(
214	                  onCheckpointSelected: (checkpoint) {
215	                    ref
216	                        .read(mapControllerProvider.notifier)
217	                        .focusOnCheckpoint(checkpoint);
218	                  },
219	                ),
220	              ),
221	
222	              // Sheet is topmost — slides up and covers controls in half/full
223	              // mode; transparent area passes touches through to the map.
224	              const Positioned.fill(child: MapBottomSheet()),
225	            ],
226	          );
227	        },
228	      ),
229	    );
230	  }
231	}
