233	// ─── Splash shown while waiting for first GPS fix ─────────────
234	
235	class _LocationAcquiringScreen extends StatelessWidget {
236	  const _LocationAcquiringScreen();
237	
238	  @override
239	  Widget build(BuildContext context) {
240	    return const Scaffold(
241	      backgroundColor: ThemeColors.bg,
242	      body: Center(
243	        child: Column(
244	          mainAxisSize: MainAxisSize.min,
245	          children: [
246	            SizedBox(
247	              width: 22,
248	              height: 22,
249	              child: CircularProgressIndicator(
250	                strokeWidth: 2,
251	                color: ThemeColors.accent,
252	              ),
253	            ),
