  // Left-hand roundabouts (UK drives on the left)
  ManeuverAction.leftRoundaboutEnter:   '$_base/left-roundabout-enter_solid_24px.png',
  ManeuverAction.leftRoundaboutPass:    '$_base/left-roundabout-pass.png',
