  // exits 8–12: no dedicated icon, fall back to exit 7
  ManeuverAction.leftRoundaboutExit8:   '$_base/left-roundabout-exit7_solid_24px.png',
  ManeuverAction.leftRoundaboutExit9:   '$_base/left-roundabout-exit7_solid_24px.png',
  ManeuverAction.leftRoundaboutExit10:  '$_base/left-roundabout-exit7_solid_24px.png',
  ManeuverAction.leftRoundaboutExit11:  '$_base/left-roundabout-exit7_solid_24px.png',
  ManeuverAction.leftRoundaboutExit12:  '$_base/left-roundabout-exit7_solid_24px.png',

  // Right-hand roundabouts (included for completeness)
  ManeuverAction.rightRoundaboutEnter:  '$_base/right-roundabout-enter_solid_24px.png',
  ManeuverAction.rightRoundaboutPass:   '$_base/right-roundabout-pass.png',
  ManeuverAction.rightRoundaboutExit1:  '$_base/right-roundabout-exit1_solid_24px.png',
  ManeuverAction.rightRoundaboutExit2:  '$_base/right-roundabout-exit2_solid_24px.png',
