  ManeuverAction.rightRoundaboutExit4:  '$_base/right-roundabout-exit4_solid_24px.png',
  ManeuverAction.rightRoundaboutExit5:  '$_base/right-roundabout-exit5_solid_24px.png',
  ManeuverAction.rightRoundaboutExit6:  '$_base/right-roundabout-exit6_solid_24px.png',
  ManeuverAction.rightRoundaboutExit7:  '$_base/right-roundabout-exit7_solid_24px.png',
