8	abstract final class UkFormatter {
9	  static const double _metersPerMile = 1609.344;
10	  static const double _yardsPerMeter = 1.09361;
11	
12	  // 0.1 mi threshold below which we show yards instead of miles.
13	  static const double _yardsThresholdMeters = _metersPerMile * 0.1; // ≈ 160.9m
14	
15	  /// Formats [meters] as a UK driving distance string.
16	  ///
17	  /// < 0.1 mi → nearest 10 yards, e.g. "170 yards"
18	  /// 0.1–9.9 mi → 1 decimal place, e.g. "2.4 mi"
19	  /// ≥ 10 mi → nearest half-mile, e.g. "12 mi" or "12.5 mi"
20	  static String formatDistance(int meters) {
21	    if (meters <= 0) return '0 yards';
22	
23	    if (meters < _yardsThresholdMeters) {
24	      final yards = (meters * _yardsPerMeter / 10).round() * 10;
25	      return '$yards yards';
26	    }
27	
28	    final miles = meters / _metersPerMile;
29	
30	    if (miles < 10.0) {
31	      final oneDecimal = (miles * 10).round() / 10;
32	      return '$oneDecimal mi';
33	    }
34	
35	    // >= 10 mi: round to nearest 0.5
36	    final halfMiles = (miles * 2).round() / 2;
37	    if (halfMiles == halfMiles.truncateToDouble()) {
38	      return '${halfMiles.toInt()} mi';
39	    }
40	    return '$halfMiles mi';
41	  }
42	
43	  /// Formats a speed in metres-per-second as mph.
44	  ///
45	  /// Returns "--" when [speedMs] is null (GPS signal lost).
46	  static String formatSpeed(double? speedMs) {
47	    if (speedMs == null) return '--';
48	    final mph = (speedMs * 2.23694).round();
49	    return '$mph mph';
50	  }
51	}
