import "package:geolocator/geolocator.dart";
import "package:ukcheckpoints_app/core/utils/logger.dart";
import 'package:riverpod_annotation/riverpod_annotation.dart';

part 'location_provider.g.dart';

enum LocationState {
  unknown,
  loading,
  permissionMissing,
  serviceDisabled,
  deniedForever,
  granted,
}

@riverpod
class LocationController extends _$LocationController {
  @override
  LocationState build() => LocationState.unknown;

  Future<void> checkStatus() async {
    state = LocationState.loading;

    final bool serviceEnabled = await Geolocator.isLocationServiceEnabled();
    if (!serviceEnabled) {
      state = LocationState.serviceDisabled;
      return;
    }

    final LocationPermission permission = await Geolocator.checkPermission();
    if (permission == LocationPermission.denied) {
      state = LocationState.permissionMissing;
    } else if (permission == LocationPermission.deniedForever) {
      state = LocationState.deniedForever;
    } else {
      state = LocationState.granted;
    }
  }

  Future<void> requestPermission() async {
    final LocationPermission permission = await Geolocator.requestPermission();
    if (permission == LocationPermission.whileInUse ||
        permission == LocationPermission.always) {
      state = LocationState.granted;
    } else if (permission == LocationPermission.deniedForever) {
      state = LocationState.deniedForever;
    } else {
      state = LocationState.permissionMissing;
    }
  }

  Future<Position?> getCurrentLocation() async {
    try {
      return await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.high,
          distanceFilter: 10,
        ),
      );
    } catch (e, st) {
      AppLogger.error("Failed to get current location", error: e, stackTrace: st);
      return null;
    }
  }
}

