              controller: scrollController,
              slivers: [
                SliverToBoxAdapter(
                  child: switch (mode) {
                    SheetMode.peek =>
                      NavPeekContent(onTap: onExpand),
                    SheetMode.fullSearch when isGuidance =>
                      const NavGuidanceFullContent(),
                    SheetMode.fullSearch =>
                      const NavFullSearchContent(),
                    // Mid or full sheet during active drive → same guidance view.
                    SheetMode.tripOverview when phase is ActiveDrive =>
                      const NavGuidanceFullContent(),
                    SheetMode.tripOverview =>
                      const NavTripOverviewContent(),
                  },
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// ── Drag handle ───────────────────────────────────────────────────────────

class _DragHandle extends StatelessWidget {
  const _DragHandle();

  @override
  Widget build(BuildContext context) {
    return const SizedBox(
      height: 28,
      child: Center(
        child: SizedBox(
          width: 36,
          height: 4,
          child: DecoratedBox(
            decoration: BoxDecoration(
              color: ThemeColors.borderStrong,
              borderRadius: BorderRadius.all(Radius.circular(2)),
            ),
