213	  // Builds a new MapMarker for a checkpoint, embedding its status in metadata
214	  // so the diff logic can detect when the icon needs refreshing.
215	  MapMarker _buildMarker(
216	    Checkpoint checkpoint,
217	    Map<ContributionStatusEnum, MapImage> icons,
218	  ) {
219	    final status = checkpoint.contributions.isNotEmpty
220	        ? checkpoint.contributions.first.status
221	        : ContributionStatusEnum.UNKNOWN;
222	    final icon = icons[status] ?? icons[ContributionStatusEnum.UNKNOWN]!;
223	    return MapMarker(
224	      GeoCoordinates(
225	        checkpoint.latitude.toDouble(),
226	        checkpoint.longitude.toDouble(),
227	      ),
228	      icon,
229	    )..metadata = (Metadata()
230	      ..setString('checkpointId', checkpoint.id)
231	      ..setString('status', status.name));
