239	  // Diffs the current marker set against the incoming checkpoints:
240	  // only removes stale markers and adds new/changed ones, in batches.
241	  void updateCheckpoints(
242	    List<Checkpoint> checkpoints,
243	    Map<ContributionStatusEnum, MapImage> icons,
244	  ) {
245	    final controller = state;
246	    if (controller == null) return;
247	
248	    final desired = {for (final c in checkpoints) c.id: c};
249	
250	    // Remove markers no longer needed.
251	    final staleIds = _markerById.keys
252	        .where((id) => !desired.containsKey(id))
253	        .toList();
254	    if (staleIds.isNotEmpty) {
255	      controller.mapScene.removeMapMarkers(
256	        staleIds.map((id) => _markerById[id]!).toList(),
257	      );
258	      staleIds.forEach(_markerById.remove);
259	    }
260	
261	    // Add new markers and refresh any whose status changed.
262	    final toAdd = <MapMarker>[];
263	    for (final checkpoint in checkpoints) {
264	      final existing = _markerById[checkpoint.id];
265	      if (existing != null) {
266	        final currentStatus = existing.metadata?.getString('status');
267	        if (currentStatus == _statusFor(checkpoint).name) continue;
268	        // Status changed — replace.
269	        controller.mapScene.removeMapMarker(existing);
270	        _markerById.remove(checkpoint.id);
271	      }
272	      final marker = _buildMarker(checkpoint, icons);
273	      toAdd.add(marker);
274	      _markerById[checkpoint.id] = marker;
275	    }
276	    if (toAdd.isNotEmpty) {
277	      controller.mapScene.addMapMarkers(toAdd);
278	    }
279	  }
