498	  Future<void> showRoute(Route route) async {
499	    final controller = state;
500	    if (controller == null) return;
501	
502	    clearRoute();
503	
504	    // Polyline: 24px blue with 6px white outline (physical pixels;
505	    // ~8dp on a 3× screen — same weight as Google Maps route line).
506	    final lineWidth = MapMeasureDependentRenderSize.withSingleSize(
507	      RenderSizeUnit.pixels,
508	      24,
509	    );
510	    final outlineWidth = MapMeasureDependentRenderSize.withSingleSize(
511	      RenderSizeUnit.pixels,
512	      6,
513	    );
514	    final rep = MapPolylineSolidRepresentation.withOutline(
515	      lineWidth,
516	      const ui.Color(0xFF3E5BFF),
517	      outlineWidth,
518	      Colors.white,
519	      LineCap.round,
520	    );
521	    final polyline = MapPolyline.withRepresentation(route.geometry, rep);
522	    controller.mapScene.addMapPolyline(polyline);
523	    _routePolyline = polyline;
524	
525	    // Origin (blue) + dest (red) circle markers.
526	    final verts = route.geometry.vertices;
527	    if (verts.isNotEmpty) {
528	      final originImg = await _circlePng(const ui.Color(0xFF3E5BFF), 20);
529	      final destImg   = await _circlePng(const ui.Color(0xFFE63946), 24);
530	
531	      // State may have been cleared while we awaited the PNG renders.
532	      if (state == null) return;
533	
534	      final originMarker = MapMarker(verts.first, originImg);
535	      final destMarker   = MapMarker(verts.last,  destImg);
536	      controller.mapScene.addMapMarker(originMarker);
537	      controller.mapScene.addMapMarker(destMarker);
538	      _routeOriginMarker = originMarker;
539	      _routeDestMarker   = destMarker;
540	    }
541	
542	    // Fit camera to the route bounding box (north-up, no tilt).
543	    controller.camera.applyUpdate(
544	      MapCameraUpdateFactory.lookAtArea(route.boundingBox),
545	    );
546	  }
547	
548	  void clearRoute() {
549	    final controller = state;
550	    if (controller == null) return;
551	
552	    if (_routePolyline != null) {
553	      controller.mapScene.removeMapPolyline(_routePolyline!);
554	      _routePolyline = null;
555	    }
556	    if (_routeOriginMarker != null) {
557	      controller.mapScene.removeMapMarker(_routeOriginMarker!);
558	      _routeOriginMarker = null;
559	    }
560	    if (_routeDestMarker != null) {
561	      controller.mapScene.removeMapMarker(_routeDestMarker!);
562	      _routeDestMarker = null;
563	    }
564	  }
