566	  // Renders a filled circle with a white halo as a PNG MapImage.
567	  Future<MapImage> _circlePng(ui.Color color, double size) async {
568	    final recorder = ui.PictureRecorder();
569	    final canvas   = ui.Canvas(recorder);
570	    final half     = size / 2;
571	    canvas
572	      ..drawCircle(
573	        ui.Offset(half, half),
574	        half,
575	        ui.Paint()..color = const ui.Color(0xFFFFFFFF),
576	      )
577	      ..drawCircle(
578	        ui.Offset(half, half),
579	        half - 2,
580	        ui.Paint()..color = color,
581	      );
582	    final picture = recorder.endRecording();
583	    final img     = await picture.toImage(size.toInt(), size.toInt());
584	    final bd      = await img.toByteData(format: ui.ImageByteFormat.png);
585	    return MapImage.withPixelDataAndImageFormat(
586	      bd!.buffer.asUint8List(),
587	      ImageFormat.png,
588	    );
589	  }
